  var byId = {};
  for (var i = 0; i < list.length; i++) if (list[i] && list[i].id) byId[list[i].id] = list[i];
  var out = [];
  for (var j = 0; j < sharers.length; j++) {
    var it = byId[sharers[j]];
    if (it && window.__bramWorklist2Begun(it, claim)) out.push(sharers[j]);
  }
  return out;
