      "font-size:12px", "line-height:1", "padding:4px 8px", "cursor:pointer",
      "border-radius:4px",
      "border:1px solid var(--xmlui-borderColor, #c8ccd2)",
      "background:var(--xmlui-backgroundColor-primary, #fff)",
      "color:var(--xmlui-textColor-primary, #222)",
