    current = pre;
    b.style.display = "block";
    var w = b.offsetWidth || 48;
    b.style.top = Math.max(0, Math.round(r.top + 4)) + "px";
    b.style.left = Math.max(0, Math.round(r.right - w - 4)) + "px";
